import { HL } from './kernel.js';

/**
 * Patch: the Rstest patch panel, five ports in a row, each with a cable
 * plugged in and a flag of tape wrapped round it that carries its adapter's
 * logo. The cable under the pointer is drawn out of its port and lifts toward
 * the viewer; its neighbours lean away, less the further away. Above each
 * port a lamp shows pass while its plug is seated and fail once it is drawn
 * out. At rest the middle cable is half out. The slider is the lean's reach,
 * in ports.
 */
const {
  Cam,
  clamp,
  fillet,
  fit,
  hull,
  open,
  poly,
  proj,
  rrect,
  run,
  seg,
  spring,
  stepS,
  disposer,
  mk,
  pointer,
  put,
  register,
  solid,
} = HL;

// The five adapter logos, unchanged from their official files.
const ICONS = {
  rstest: {
    w: 217,
    h: 200,
    src: 'data:image/svg+xml;base64,',
  },
  rsbuild: {
    w: 2500,
    h: 2345,
    src: 'data:image/svg+xml;base64,',
  },
  rslib: {
    w: 1110,
    h: 983,
    src: 'data:image/svg+xml;base64,',
  },
  rspack: {
    w: 578,
    h: 449,
    src: 'data:image/svg+xml;base64,',
  },
  modernjs: {
    w: 40,
    h: 33,
    src: 'data:image/svg+xml;base64,',
  },
  lynx: {
    w: 27,
    h: 28,
    paths: [
      'M7.56542 6.19594L3.90642 8.7164C3.50877 8.99031 3.23346 9.40191 3.13675 9.86708L2.77902 11.5878C2.76005 11.679 2.71799 11.7642 2.65665 11.8355L0.996306 14.0121C0.772761 14.2722 0.778152 14.9632 1.39044 15.4057C1.62523 15.6103 1.93915 16.0691 2.29622 16.591C3.05224 17.6959 4.00169 19.0836 4.80312 18.9394C5.9372 18.541 7.32544 18.4135 8.39128 18.9394C10.4632 20.7282 9.95449 22.3775 9.22514 24.7421C8.93165 25.6936 8.60243 26.7609 8.39128 27.9997C9.38643 24.3777 11.6242 20.1711 15.6592 18.7437C14.9322 18.1498 13.4486 17.5981 12.1357 17.4653C12.1357 17.4653 16.1691 14.0121 21.1439 12.4254C17.671 4.16205 11.9386 0.213095 11.9386 0.213095C11.6465 -0.148197 11.0566 -0.0296711 10.9349 0.414774C10.8371 1.72112 10.675 2.60942 10.4074 3.44676L8.39128 1.12029C8.18068 0.866399 7.75965 1.013 7.76176 1.33949C8.10312 3.23719 8.05521 4.30239 7.56542 6.19594ZM8.9846 6.02248L8.99663 6.02171C9.02298 6.02002 9.0489 6.01659 9.07424 6.01153L8.9846 6.02248ZM11.7123 1.7617C13.094 4.1491 13.7199 5.5054 13.9322 8.03659C12.4625 7.2017 11.8221 6.98923 10.7413 6.99451C11.3718 5.0773 11.5644 3.92284 11.7123 1.7617Z',
      'M20.5916 19.4929C14.9639 20.7806 11.7672 22.7198 9.32227 28.0001C13.7111 20.6367 26.9966 21.9536 26.9966 21.9536C26.7484 20.7508 24.1069 18.4571 22.3696 17.0503C22.3696 17.0503 23.7712 15.3272 26.8697 14.455C26.8697 14.455 20.9125 14.8002 17.4445 16.6727C18.568 17.2656 20.0071 18.2663 20.5916 19.4929Z',
    ],
  },
};

/** A logo laid on a flat face: draw(o, ex, ey) centres it on world point o, ex and ey being the face's unit right and up. */
function decal(parent, P, icon, size) {
  const g = mk('g', {}, parent),
    k = size / Math.max(icon.w, icon.h);
  // a colour logo is its own image; Lynx's one-colour mark takes the dot fill, so it follows the theme
  const els = icon.src
    ? [mk('image', { href: icon.src, width: icon.w, height: icon.h }, g)]
    : icon.paths.map((d) =>
        mk('path', { d, class: 'dot m', 'fill-rule': 'evenodd' }, g),
      );
  return {
    g,
    light(on) {
      if (!icon.src)
        els.forEach((el) => el.setAttribute('class', on ? 'dot' : 'dot m'));
    },
    /** Places it straight on the screen: c its centre, ex and ey unit screen vectors for its right and up, s screen units per world unit. */
    place(c, ex, ey, s) {
      const q = k * s,
        pu = [ex[0] * q, ex[1] * q],
        pv = [-ey[0] * q, -ey[1] * q];
      const p0 = [
        c[0] - (pu[0] * icon.w) / 2 - (pv[0] * icon.h) / 2,
        c[1] - (pu[1] * icon.w) / 2 - (pv[1] * icon.h) / 2,
      ];
      g.setAttribute(
        'transform',
        `matrix(${pu[0]} ${pu[1]} ${pv[0]} ${pv[1]} ${p0[0]} ${p0[1]})`,
      );
    },
    draw(o, ex, ey) {
      const at = (u, v) => {
        const a = (u - icon.w / 2) * k,
          b = (icon.h / 2 - v) * k;
        return P(
          o[0] + a * ex[0] + b * ey[0],
          o[1] + a * ex[1] + b * ey[1],
          o[2] + a * ex[2] + b * ey[2],
        );
      };
      const p0 = at(0, 0),
        pu = at(1, 0),
        pv = at(0, 1);
      g.setAttribute(
        'transform',
        `matrix(${pu[0] - p0[0]} ${pu[1] - p0[1]} ${pv[0] - p0[0]} ${pv[1] - p0[1]} ${p0[0]} ${p0[1]})`,
      );
    },
  };
}
const NAMES = ['rsbuild', 'rslib', 'rspack', 'lynx', 'modernjs'],
  N = 5,
  REST = 2;
const PITCH = 34,
  EAR = 14,
  LAB = 36,
  MAR = 6,
  H = 40,
  T = 2.6,
  DEEP = 16,
  CZ = 22;
const X0 = EAR + LAB,
  W = X0 + N * PITCH + MAR + EAR;
const LZ = 35.4,
  LR = 1.2,
  SEAT = 0.3;
const JW = 5,
  JH = 4.2,
  NW = 1.9,
  NH = 1.7,
  PW = 4.3,
  PH = 3.5,
  PL = 4,
  BL = 5,
  CR = 1.8;
const DROP = 48,
  OUT = 6,
  LEAN = 10,
  LIFT = 12,
  FW = 19,
  FH = 15,
  AT = 0.5,
  S = 1.42;
const JIT = (p) => [((p * 7) % 5) - 2, ((p * 11) % 7) - 3];
const falloff = (d, r) => (d === 0 ? 0 : clamp(1 - (d - 1) / r, 0, 1));

/** The two edges, at distance w either side, of the screen polyline q, and its tangents. */
function sides(q, w) {
  const n = q.length,
    L = [],
    R = [],
    tan = [];
  for (let i = 0; i < n; i++) {
    const a = q[Math.max(0, i - 1)],
      b = q[Math.min(n - 1, i + 1)],
      l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1,
      t = [(b[0] - a[0]) / l, (b[1] - a[1]) / l];
    tan.push(t);
    L.push([q[i][0] - t[1] * w, q[i][1] + t[0] * w]);
    R.push([q[i][0] + t[1] * w, q[i][1] - t[0] * w]);
  }
  return [L, R, tan];
}
/** A cable as a closed outline of width w round the screen polyline q, with round ends. */
function tube(q, w) {
  const n = q.length,
    [L, R, tan] = sides(q, w);
  const cap = (c, t, s) =>
    [1, 2, 3, 4, 5].map((k) => {
      const th = (k / 6) * Math.PI,
        cs = Math.cos(th),
        sn = Math.sin(th);
      return [
        c[0] + s * w * (-t[1] * cs + t[0] * sn),
        c[1] + s * w * (t[0] * cs + t[1] * sn),
      ];
    });
  return poly([
    ...L,
    ...cap(q[n - 1], tan[n - 1], 1),
    ...R.reverse(),
    ...cap(q[0], tan[0], -1),
  ]);
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let reach = value,
    over = -1,
    lit = null;
  const C = Cam(45, 0.5, S);
  const lowZ = CZ - DROP - 6,
    tipZ = CZ - DROP + LIFT + 4;
  fit(
    C,
    [
      [0, -DEEP, H],
      [W, -DEEP, H],
      [0, 0, 0],
      [W, 0, 0],
      [X0, 40, tipZ],
      [W - EAR, 40, lowZ],
      [X0, 40, lowZ],
    ],
    200,
    166,
  );
  const P = proj(C);
  const at = (ring, cx, y, cz) => ring.map((q) => P(cx + q.u, y, cz + q.v));
  const seen = (q) => 0.612 * q.nu + 0.5 * q.nv > 0;
  const slab = (ring, inner, cx, cz, y0, y1) => ({
    sil: poly(hull(at(ring, cx, y0, cz).concat(at(ring, cx, y1, cz)))),
    crease: open(at(run(inner, seen), cx, y1, cz)),
  });
  const flat = (ring) => ring.map((q) => [q.u, q.v]);

  const g = mk('g', {}, svg);
  const face = (pts, cls) =>
    mk('path', { d: poly(pts.map(([x, z]) => P(x, 0, z))), class: cls }, g);
  // the chassis behind the face, then the face plate
  put(solid(g), {
    sil: poly(
      hull(
        at(rrect(EAR + 2, 3, W - EAR - 2, H - 3, 3, 4), 0, -DEEP, 0).concat(
          at(rrect(EAR + 2, 3, W - EAR - 2, H - 3, 3, 4), 0, -T, 0),
        ),
      ),
    ),
    crease: '',
  });
  put(
    solid(g),
    slab(
      rrect(0, 0, W, H, 3, 4),
      rrect(0.7, 0.7, W - 0.7, H - 0.7, 2.3, 4),
      0,
      0,
      -T,
      0,
    ),
  );
  // the Rstest mark, printed on the face midway between the face's left edge and the port bay, so its gaps either side are equal
  decal(g, P, ICONS.rstest, 22).draw(
    [(X0 - 2) / 2, 0, H / 2],
    [1, 0, 0],
    [0, 0, 1],
  );
  face(
    flat(
      rrect(X0 - 2, CZ - JH - 4, X0 + N * PITCH + 2, CZ + JH + NH + 3, 2.4, 4),
    ),
    'lo nf',
  );
  const lampAt = (x, z) => {
    const el = face(
      flat(rrect(x - LR, z - LR, x + LR, z + LR, LR, 4)),
      'dot off',
    );
    el.setAttribute('data-led', 'fail');
    return el;
  };

  const jack = [
    [-JW, -JH],
    [JW, -JH],
    [JW, JH],
    [NW, JH],
    [NW, JH + NH],
    [-NW, JH + NH],
    [-NW, JH],
    [-JW, JH],
  ];
  const plugR = rrect(-PW, -PH, PW, PH, 1.2, 3),
    plugIn = rrect(-PW + 0.7, -PH + 0.7, PW - 0.7, PH - 0.7, 0.6, 3);
  const bootA = rrect(-3.7, -3, 3.7, 3, 1.6, 3),
    bootB = rrect(-2.4, -2.4, 2.4, 2.4, 2.3, 3);
  const ports = NAMES.map((n, p) => {
    const cx = X0 + (p + 0.5) * PITCH;
    face(
      jack.map(([u, v]) => [cx + u, CZ + v]),
      'nf',
    );
    const lamp = lampAt(cx, LZ),
      pg = mk('g', { 'data-port': n }, g),
      plug = solid(pg),
      latch = mk('path', { class: 'lo nf' }, plug.g),
      boot = solid(pg);
    const cable = mk('path', { class: 'sil' }, pg),
      tag = solid(pg),
      wrap = mk('path', { class: 'fo' }, pg),
      band = mk('path', { class: 'nf sil' }, pg);
    return {
      p,
      cx,
      lamp,
      on: null,
      plug,
      latch,
      boot,
      cable,
      tag,
      wrap,
      band,
      icon: decal(tag.g, P, ICONS[n], FH - 3),
      pull: spring(0, { eps: 0.002 }),
      lx: spring(0, { eps: 0.01 }),
      drawn: '',
    };
  });

  function drawPort(pt) {
    const k = pt.pull.x,
      lx = pt.lx.x,
      key = k.toFixed(3) + lx.toFixed(3);
    if (key === pt.drawn) return;
    pt.drawn = key;
    // seated means the plug is nearly home: its lamp shows pass; drawn out, it shows fail
    if (k < SEAT !== pt.on) {
      pt.on = k < SEAT;
      pt.lamp.setAttribute('class', pt.on ? 'dot' : 'dot off');
      pt.lamp.setAttribute('data-led', pt.on ? 'pass' : 'fail');
    }
    const { cx, p } = pt,
      y1 = PL + OUT * k,
      y2 = y1 + BL,
      [jx, jz] = JIT(p);
    put(pt.plug, slab(plugR, plugIn, cx, CZ, 0, y1));
    pt.latch.setAttribute(
      'd',
      seg(P(cx, 0.6, CZ + PH), P(cx, y1 - 0.8, CZ + PH)),
    );
    put(pt.boot, {
      sil: poly(hull(at(bootA, cx, y1, CZ).concat(at(bootB, cx, y2, CZ)))),
      crease: '',
    });
    // the cable bends down from the boot and on out of the picture; drawn out, it rises toward the viewer
    const p0 = [cx, y2 - 1.5, CZ],
      p1 = [cx + 0.5, y2 + OUT + 6 * k, CZ];
    const p3 = [
        cx + 2 + jx + lx,
        y2 + OUT + 2 + LIFT * k,
        CZ - DROP - jz + LIFT * k,
      ],
      p2 = [p3[0] - 0.6, p3[1] - 1, p3[2] + 12];
    const w = [];
    for (let i = 0; i <= 40; i++) {
      const s = i / 40,
        a = (1 - s) ** 3,
        b = 3 * (1 - s) ** 2 * s,
        c = 3 * (1 - s) * s * s,
        d = s ** 3;
      w.push(
        [0, 1, 2].map((j) => a * p0[j] + b * p1[j] + c * p2[j] + d * p3[j]),
      );
    }
    pt.cable.setAttribute(
      'd',
      tube(
        w.map((v) => P(...v)),
        CR * S,
      ),
    );
    // a strip of tape wrapped once round the cable, its two ends stuck together into a flag beside it.
    // The tape's run is sampled at fixed arc lengths, so it slides smoothly with the cable instead of snapping between samples.
    const len = [0];
    for (let i = 1; i < w.length; i++)
      len.push(
        len[i - 1] + Math.hypot(...[0, 1, 2].map((j) => w[i][j] - w[i - 1][j])),
      );
    const mid = len[len.length - 1] * AT,
      along = (d) => {
        let i = 1;
        while (i < len.length - 1 && len[i] < d) i++;
        return [0, 1, 2].map(
          (j) =>
            w[i - 1][j] +
            (w[i][j] - w[i - 1][j]) *
              ((d - len[i - 1]) / (len[i] - len[i - 1] || 1)),
        );
      };
    const side = Array.from({ length: 9 }, (_, k) =>
      along(mid + (k / 8 - 0.5) * FH),
    );
    // the wrap itself: as wide as the cable, so only its two edges and its two seams show; no round ends, so it never covers the flag
    const wq = side.map((c) => P(c[0], c[1] + 0.6, c[2])),
      wr = CR * S + 0.35,
      [L, R, tan] = sides(wq, wr);
    // the flag is the tape's two ends stuck together: it leaves the wrap along the wrap's own edge and seams, on the right of the cable
    const pick = (pair) => (pair[0][4][0] > pair[1][4][0] ? pair[0] : pair[1]);
    const near = pick([L, R]),
      out = pick(sides(wq, wr + FW * S)),
      fold = pick(sides(wq, wr + 1.6 * S));
    const round = side.map((_, i) =>
      i === 0 || i === side.length - 1 ? 1.6 * S : 0,
    );
    pt.tag.sil.setAttribute(
      'd',
      poly(
        fillet(
          near.concat(out.slice().reverse()),
          side.map(() => 0).concat(round),
          3,
        ),
      ),
    );
    pt.wrap.setAttribute('d', poly(L.concat(R.slice().reverse())));
    pt.band.setAttribute(
      'd',
      open(L) +
        open(R) +
        seg(L[0], R[0]) +
        seg(L[L.length - 1], R[R.length - 1]),
    );
    const nx = out[4][0] - near[4][0],
      ny = out[4][1] - near[4][1],
      nl = Math.hypot(nx, ny),
      t = tan[4];
    pt.icon.place(
      [(fold[4][0] + out[4][0]) / 2, (fold[4][1] + out[4][1]) / 2],
      [nx / nl, ny / nl],
      [-t[0], -t[1]],
      S,
    );
  }

  function aim(a, r, depth) {
    for (const pt of ports) {
      const dx = pt.p - a,
        f = falloff(Math.abs(dx), r) * depth;
      pt.pull.t = dx === 0 ? depth : 0;
      pt.lx.t = dx ? clamp(Math.sign(dx) * f * LEAN, -LEAN, LEAN) : 0;
    }
  }
  const mark = (q, on) => {
    [q.plug.sil, q.boot.sil, q.cable, q.tag.sil, q.band].forEach((el) =>
      el.classList.toggle('hi', on),
    );
    q.icon.light(on);
  };
  const light = (pt) => {
    if (pt !== lit) {
      if (lit) mark(lit, false);
      mark((lit = pt), true);
    }
  };
  aim(REST, 1.6, 0.55);
  for (const pt of ports) for (const s of [pt.pull, pt.lx]) s.x = s.t;
  light(ports[REST]);
  read.textContent = 'rest';

  const B = register(stage, (dt) =>
    ports
      .map((pt) => {
        const m = [pt.pull, pt.lx].map((s) => stepS(s, dt)).some(Boolean);
        drawPort(pt);
        return m;
      })
      .some(Boolean),
  );
  bag.add(B.unregister);

  // hit: the pointer on the plane just in front of the face, which never moves; x picks the port, z must be on the panel or its tags
  const o = P(0, 2.5, 0),
    ux = P(1, 2.5, 0),
    uz = P(0, 2.5, 1);
  const ex = [ux[0] - o[0], ux[1] - o[1]],
    ez = [uz[0] - o[0], uz[1] - o[1]],
    det = ex[0] * ez[1] - ex[1] * ez[0];
  function hit([sx, sy]) {
    const qx = sx - o[0],
      qy = sy - o[1],
      x = (qx * ez[1] - qy * ez[0]) / det,
      z = (ex[0] * qy - ex[1] * qx) / det;
    if (x < X0 - 4 || x > X0 + N * PITCH + 4 || z < lowZ - 20 || z > H + 4)
      return -1;
    return clamp(Math.floor((x - X0) / PITCH), 0, N - 1);
  }
  function retarget() {
    if (over >= 0) {
      aim(over, reach, 1);
      light(ports[over]);
      read.textContent = NAMES[over];
    } else {
      aim(REST, 1.6, 0.55);
      light(ports[REST]);
      read.textContent = 'rest';
    }
    B.wake();
  }
  bag.add(
    pointer(stage, {
      move: (p) => {
        const h = hit(p);
        if (h !== over) {
          over = h;
          retarget();
        }
      },
      leave: () => {
        over = -1;
        retarget();
      },
    }),
  );
  bag.add(() => svg.replaceChildren());
  // port(point) names the port a viewBox point is over, by the same rest-pose hit, so a host can link each plug
  return {
    set: (v) => {
      reach = v;
      if (over >= 0) retarget();
    },
    destroy: bag.dispose,
    port: (q) => NAMES[hit(q)],
  };
}

const MEANS =
  'Five adapter cables patched into Rstest: each lamp shows pass when seated and fail when drawn; the one under the pointer draws out.';
// Each port's highlight and lamp colours, from the logos; kept out of the figure, which takes the kernel's classes only.
const TINT =
  "[data-hairline] [data-port] { --tint: var(--hl-hi); } [data-hairline] [data-port='rsbuild'] { --tint: #ff5a5a; } [data-hairline] [data-port='rslib'] { --tint: #9870e3; } [data-hairline] [data-port='rspack'] { --tint: #f67954; } [data-hairline] [data-port='modernjs'] { --tint: #4ecaff; } [data-hairline] [data-port]:not([data-port='lynx']) { --hl-hi: color-mix(in oklab, var(--tint) 85%, var(--hl-edge)); } [data-hairline] [data-led='pass'] { --hl-hi: color-mix(in oklab, #05b78b 85%, var(--hl-edge)); } [data-hairline] [data-led='fail'] { --hl-lo: color-mix(in oklab, #e5484d 85%, var(--hl-edge)); }";

/** Mounts the figure in `host` the way the package does, with a fixed reach, and plays its tour when asked. Returns the tear-down. */
export function mountPatch(host, { value = 2, play = true, onPick } = {}) {
  const doc = host.ownerDocument;
  HL.inject(doc);
  if (!doc.getElementById('hairline-patch-tint')) {
    const style = doc.createElement('style');
    style.id = 'hairline-patch-tint';
    style.textContent = TINT;
    doc.head.appendChild(style);
  }
  host.setAttribute('data-hairline', 'patch');
  host.setAttribute('role', 'img');
  host.setAttribute('aria-label', MEANS);
  const svg = HL.mk(
    'svg',
    { viewBox: '0 0 400 320', 'aria-hidden': 'true' },
    host,
  );
  const figure = mount({ stage: host, svg, read: { textContent: '' } }, value);
  // a click on a port hands its adapter's name to onPick; the cursor says which points are links
  const at = (e) => {
    const r = host.getBoundingClientRect();
    return figure.port([
      ((e.clientX - r.left) / r.width) * 400,
      ((e.clientY - r.top) / r.height) * 320,
    ]);
  };
  const move = (e) => {
    host.style.cursor = onPick && at(e) ? 'pointer' : '';
  };
  const click = (e) => {
    const name = at(e);
    if (name) onPick?.(name);
  };
  host.addEventListener('pointermove', move);
  host.addEventListener('click', click);
  // one stop per port, left to right, then rest
  const lap = play
    ? HL.tour(host, [
        [133, 112],
        [167, 129],
        [201, 146],
        [236, 163],
        [270, 180],
        null,
      ])
    : null;
  return () => {
    lap?.stop();
    host.removeEventListener('pointermove', move);
    host.removeEventListener('click', click);
    host.style.cursor = '';
    figure.destroy();
    svg.remove();
    for (const name of ['data-hairline', 'role', 'aria-label'])
      host.removeAttribute(name);
  };
}
